{
  "segment_function": "argument",
  "claims": [
    {
      "claim": "The concept of process, common to nineteenth-century sciences, originated from introspection of the biological life process within our bodies, aligning with the activity of labor.",
      "claim_type": "author_position",
      "supporting_excerpt": "What all these theories in the various sciences—economics, history, biology, geology—have in common is the concept of process, which was virtually unknown prior to the modern age. Since the discovery of processes by the natural sciences had coincided with the discovery of introspection in philosophy, it is only natural that the biological process within ourselves should eventually become the very model of the new concept; within the framework of experiences given to introspection, we know of no other process but the life process within our bodies, and the only activity into which we can translate it and which corresponds to it is labor.",
      "support_kind": "direct",
      "confidence": 1
    },
    {
      "claim": "Labor's products and the laboring activity itself remain strictly private, worldless, and incapable of establishing a common world, leading ultimately to worldless hobbies under socialized mankind.",
      "claim_type": "author_position",
      "supporting_excerpt": "Neither abundance of goods nor the shortening of the time actually spent in laboring are likely to result in the establishment of a common world, and the expropriated animal laborans becomes no less private because he has been deprived of a private place of his own to hide and be protected from the common realm.",
      "support_kind": "direct",
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "animal laborans",
      "definition": "Man conceptualized through the life process and labor, driven by the needs of the body and oblivious of the world to the point of worldlessness."
    }
  ],
  "distinctions": [
    {
      "item_a": "homo faber",
      "item_b": "animal laborans",
      "distinction": "Homo faber uses his hands and primordial tools freely, whereas animal laborans is driven by bodily needs and does not use the body freely."
    }
  ],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "The connection between the modern concept of process, introspection, biological life, and labor.",
    "The distinction between animal laborans and homo faber regarding bodily freedom and necessity.",
    "The emergence of worldlessness and private hobbies under socialized mankind."
  ]
}

